def test_returns_original_objects_without_mutation():
    e1 = {"id": "a", "version": 1}
    e2 = {"id": "a", "version": 2}
    events = [e1, e2]
    result = dedupe(events)
    assert result[0] is e2
    assert events == [e1, e2]

def test_large_stream():
    events = [{"id": f"e{i % 1000}", "version": i} for i in range(100_000)]
    result = dedupe(events)
    assert len(result) == 1000
    assert result[0] == {"id": "e0", "version": 99_000}

solution.code:
def dedupe(events: list[dict]) -> list[dict]:
    best: dict[str, dict] = {}
    for event in events:
        current = best.get(event["id"])
        if current is None or event["version"] >= current["version"]:
            best[event["id"]] = event
    return list(best.values())
